import{z as o,x as A,o as E,c as p,q as e,j as s,D as m,d as i,s as n,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"回报、折扣与价值函数","description":"","frontmatter":{"title":"回报、折扣与价值函数","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/return-discounting.md","filePath":"llm/return-discounting.md","lastUpdated":1791413859000}'),B={name:"llm/return-discounting.md"};function d(g,a,_,u,D,c){const r=A("Mermaid");return E(),p("div",null,[a[2]||(a[2]=e('<h1 id="回报、折扣与价值函数" tabindex="-1">回报、折扣与价值函数 <a class="header-anchor" href="#回报、折扣与价值函数" aria-label="Permalink to &quot;回报、折扣与价值函数&quot;">​</a></h1><div class="epigraph"><p>价值不是这一步拿到了多少，而是从这一步往后还能拿到多少的折扣总和；决策比较的从来是后者。</p><footer>—— 据 Sutton &amp; Barto, Reinforcement Learning: An Introduction, 2018, 第 3 章；折扣表述见 Howard, Dynamic Programming and Markov Processes, 1960 整理</footer></div><p><a href="/llm/mdp-five-tuple">上一课</a>把序贯决策钉成五元组 \\((S,A,P,r,\\gamma)\\) 与轨迹分布，把优化目标写成对 \\(p^\\pi\\) 的期望；但「期望什么」还没定义——一条轨迹只给出一列奖励，怎么把它压成一个可以比较的数。本课补这个缺口：回报 \\(G_t\\) 与折扣因子 \\(\\gamma\\)，以及价值函数 \\(V^\\pi\\) 与动作价值函数 \\(Q^\\pi\\)；并给 \\(\\gamma\\) 三种读法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>奖励流 \\(r_0,r_1,r_2,\\dots\\) 无限长，直接求和可能发散，两个「无穷」没法比较；而且各时刻的奖励量纲相同却意义不同：眼前的分数与一千步之后的分数不在一个价位上。<span class="marginnote">直觉类比：这和金融里的折现是一回事——一年后到账的一块钱，今天不值一块钱，要打个折才等值。\\(\\gamma\\) 就是这个折扣率的近亲：\\(\\gamma^{100}\\) 表示「100 步之后的奖励折算到今天还剩几成」。折扣不是嫌远期奖励不重要，而是给「未来」一个统一的汇率，让不同时刻的钱能加到一起。</span>吃糖一步爽而长期有害，说的就是「每步奖励之和」与「这个状态值得去吗」是两回事。决策需要一个把「从现在起的全部未来」折叠成单个实数的泛函。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>回报定义为折扣和：</p> \\[G_t=\\sum_{k=0}^{\\infty}\\gamma^k r_{t+k},\\qquad \\gamma\\in[0,1) \\]<p>价值函数与动作价值函数是回报的条件期望：</p> \\[V^\\pi(s)=\\mathbb{E}_\\pi[G_t\\mid s_t=s],\\qquad Q^\\pi(s,a)=\\mathbb{E}_\\pi[G_t\\mid s_t=s,\\ a_t=a] \\]<p>两者由策略加权相连：\\(V^\\pi(s)=\\sum_a \\pi(a\\mid s)\\,Q^\\pi(s,a)\\)；而 \\(Q^\\pi\\) 比期望再多走一步：\\(Q^\\pi(s,a)=r(s,a)+\\gamma\\,\\mathbb{E}_{s&#39;\\sim P}[V^\\pi(s&#39;)]\\)。\\(V\\) 评「处境」，\\(Q\\) 评「处境里的这个动作」；后面策略改进要用 \\(Q\\)（换 argmax 的动作），基线要用 \\(V\\)（减去处境均值），分工在此埋下。</p><p>\\(\\gamma\\) 有三种读法，各有用处：</p><ol><li><strong>时间偏好</strong>：\\(\\gamma\\) 近 \\(1\\) 是耐心，远期与近期几乎同权；\\(\\gamma=0\\) 只看眼前一步。它把「多远的事还算数」写成单个参数。</li><li><strong>有效视界</strong>：几何级数主要质量集中在约 \\(1/(1-\\gamma)\\) 步内。\\(\\gamma=0.99\\) 视界约百步，\\(\\gamma=0.999\\) 约千步。<span class="marginnote">数字实例：\\(\\gamma=0.99\\) 时，100 步后的奖励权重只剩 \\(0.99^{100}\\approx 0.37\\)，500 步后约 \\(0.0066\\)——基本可以忽略；把 \\(\\gamma\\) 调到 \\(0.999\\)，同样的 0.37 要到 1000 步才出现。若每步奖励上限是 1，回报的总上界 \\(1/(1-\\gamma)\\) 也从 100 变成 1000：同一个数既控视界也控有界性。</span></li><li><strong>几何收敛</strong>：\\(|G_t|\\le r_{\\max}/(1-\\gamma)\\)，无穷和有界；这是后面贝尔曼算子成为压缩映射的前提之一。</li></ol>',13)),(E(),s(l,null,{default:m(()=>[n(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20RS%5B%22%E5%A5%96%E5%8A%B1%E6%B5%81%20r_t%2C%20r_%7Bt%2B1%7D%2C%20...%22%5D%20--%3E%20G%5B%22%E6%8A%98%E6%89%A3%E5%92%8C%20G_t%22%5D%0A%20%20GAMMA%5B%22%E6%8A%98%E6%89%A3%E5%9B%A0%E5%AD%90%20%CE%B3%22%5D%20--%3E%20G%0A%20%20G%20--%3E%20V%5B%22V%5Epi(s)%EF%BC%9A%E7%BB%99%E5%AE%9A%20s%20%E7%9A%84%E6%9C%9F%E6%9C%9B%E5%9B%9E%E6%8A%A5%22%5D%0A%20%20G%20--%3E%20Q%5B%22Q%5Epi(s%2Ca)%EF%BC%9A%E7%BB%99%E5%AE%9A%20s%2Ca%20%E7%9A%84%E6%9C%9F%E6%9C%9B%E5%9B%9E%E6%8A%A5%22%5D%0A%20%20V%20--%3E%20REL%5B%22%E7%AD%96%E7%95%A5%E5%8A%A0%E6%9D%83%E7%9B%B8%E8%BF%9E%22%5D%0A%20%20Q%20--%3E%20REL%0A"})]),fallback:m(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[i("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"价值函数为什么是正确的中间量：它把「无限长的未来」折成每个状态一个数，于是「规划整条轨迹」降维成「比较几个数」。没有这一步，决策要在指数多的轨迹上做选择；有了它，状态取代轨迹成为运算对象。代价也在这里：\\(V^\\pi\\) 是期望，条件在策略上——换策略就换价值，\\(V^\\pi\\) 不是「这个状态客观上多好」，而是「这个状态在 \\(\\pi\\) 手里多好」。混淆两者会在后面把评估与改进搅在一起。",-1)),a[5]||(a[5]=t("p",null,"\\(\\gamma\\) 的改动不是调参而是换目标：视界从百步变千步，早期步骤的信用被重新放大。上面第二种读法解释了后训练里一个常见现象——把折扣从 \\(0.99\\) 调到 \\(0.999\\)，长推理链的行为显著改变：不是模型变了，是问题定义变了。",-1)),(E(),s(l,null,{default:m(()=>[n(r,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20G0%5B%22%CE%B3%20%3D%200%22%5D%20--%3E%20H0%5B%22%E5%8F%AA%E7%9C%8B%E7%9C%BC%E5%89%8D%E4%B8%80%E6%AD%A5%20%E8%B4%AA%E5%BF%83%E8%A7%86%E9%87%8E%22%5D%0A%20%20G1%5B%22%CE%B3%20%3D%200.99%22%5D%20--%3E%20H1%5B%22%E8%A7%86%E7%95%8C%E7%BA%A6%20100%20%E6%AD%A5%20%E7%9F%AD%E5%B1%80%E4%BB%BB%E5%8A%A1%22%5D%0A%20%20G2%5B%22%CE%B3%20%3D%200.999%22%5D%20--%3E%20H2%5B%22%E8%A7%86%E7%95%8C%E7%BA%A6%201000%20%E6%AD%A5%20%E9%95%BF%E6%8E%A8%E7%90%86%E9%93%BE%22%5D%0A%20%20H0%20--%3E%20P%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%E5%A5%96%E5%8A%B1%E6%B5%81%20%E8%A2%AB%E6%8A%98%E6%88%90%E4%B8%8D%E5%90%8C%E7%9A%84%E4%BB%B7%E5%80%BC%22%5D%0A%20%20H1%20--%3E%20P%0A%20%20H2%20--%3E%20P%0A%20%20P%20--%3E%20W%5B%22%E6%94%B9%20%CE%B3%20%E4%B8%8D%E6%98%AF%E8%B0%83%E5%8F%82%20%E6%98%AF%E6%8D%A2%E9%97%AE%E9%A2%98%E5%AE%9A%E4%B9%89%22%5D%0A"})]),fallback:m(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=e('<p><span class="marginnote">常见误区：把 \\(\\gamma\\) 当成学习率那样的纯数值旋钮去网格搜索。学习率只影响「多快找到答案」，\\(\\gamma\\) 决定「答案是什么」——两组不同 \\(\\gamma\\) 下的回报不可直接比较，A/B 出来的「谁分高」比的其实是两道不同的题。每次改 \\(\\gamma\\)，都应视为重新定义了任务。</span></p><p><span class="marginnote">\\(\\gamma=1\\) 在回合有限（必到 EOS）时也可用，但要求终止有保证；一旦轨迹可能无限长，\\(\\gamma\\lt 1\\) 就从选项变成必需品——它同时管发散和管收敛。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课只定义，不给算法：\\(V^\\pi\\) 按定义要枚举所有轨迹，实际不可算——把它变成递归方程是下一课的事。也不讲平均奖励准则（无折扣、比长期步均值的另一套理论，视界语义完全不同）。\\(V\\) 与 \\(Q\\) 的关系式在本课只是代数，下一课它会升级成方程。</p><p>后课默认：\\(G_t\\) 是折扣回报，\\(V^\\pi\\)/\\(Q^\\pi\\) 是它的条件期望，\\(1/(1-\\gamma)\\) 是视界尺度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>回报 \\(G_t=\\sum_k\\gamma^k r_{t+k}\\) 把奖励流折成一个可比较的实数。</li><li>\\(V^\\pi\\) 评处境，\\(Q^\\pi\\) 评动作；策略加权相连，\\(Q\\) 比 \\(V\\) 多看一步。</li><li>\\(\\gamma\\) 三读法：时间偏好、有效视界 \\(1/(1-\\gamma)\\)、几何有界性（压缩的前提）。</li><li>价值条件在策略上，换策略即换价值；改 \\(\\gamma\\) 是换问题不是调参。</li><li>定义不可算：枚举轨迹指数级，递归化留给贝尔曼方程。</li><li>出处：Sutton &amp; Barto, <em>Reinforcement Learning</em>, 2018 第 3 章；Howard, <em>Dynamic Programming and Markov Processes</em>, 1960。</li></ul>',7))])}const f=o(B,[["render",d]]);export{h as __pageData,f as default};
